function load(force = false) {
    const current = user(); const client = db();
    if (!isStudent() || !current || !client) return;
    if (!force && state.loaded && state.userId === current.id) return render();
    Object.assign(state, { userId:current.id, loading:true, loaded:false, linked:false, error:'', errors:[], student:null, photoPath:'', photoUrl:'', grades:[], attendance:[], activities:[], events:[], announcements:[], messages:[], sessions:[], achievements:[] });
    loadPrefs(); render();
    try {
      const links = await client.from('guardian_students').select('student_id').eq('profile_id', current.id).limit(2);
      if (links.error) { state.error = 'Não foi possível verificar seu vínculo escolar.'; return; }
      const studentId = links.data?.[0]?.student_id;
      if (!studentId) { state.loaded = true; return; }
      const studentResult = await client.from('students').select('id,official_name,class_id,active,classes(id,year,class_code,shift)').eq('id', studentId).eq('active', true).maybeSingle();
      if (studentResult.error || !studentResult.data) { state.error = 'O cadastro do aluno não está disponível neste momento.'; return; }
       state.student = studentResult.data; state.linked = true;
       const photo = await loadPhoto(client, studentId);
       state.photoPath = photo.path;
       state.photoUrl = photo.url;
      const classId = state.student.class_id;
      let activitiesQuery = client.from('school_activities').select('id,title,subject,description,due_date,published_at,class_id').order('due_date', { ascending:true }).limit(30);
      if (classId) activitiesQuery = activitiesQuery.or(`class_id.is.null,class_id.eq.${classId}`); else activitiesQuery = Promise.resolve({ data:[], error:null });
      const [grades, attendance, events, announcements, messages, sessions, achievements, activities] = await Promise.all([
        rows('grades', client.from('grades').select('id,subject,assessment,score,term,created_at').eq('student_id', studentId).order('created_at', { ascending:false }).limit(100)),
        rows('attendance', client.from('attendance').select('attendance_date,status').eq('student_id', studentId).order('attendance_date', { ascending:false }).limit(200)),
        rows('events', client.from('school_events').select('title,description,starts_at,location').gte('starts_at', new Date().toISOString()).order('starts_at').limit(8)),
        rows('announcements', client.from('announcements').select('id,title,body,published_at,important').eq('status','published').eq('audience_mode','all').order('published_at', { ascending:false }).limit(8)),
        rows('messages', client.from('student_messages').select('id,body,category,created_at').eq('student_id', studentId).or(`recipient_id.eq.${current.id},sender_id.eq.${current.id}`).order('created_at', { ascending:false }).limit(8)),
        rows('sessions', client.from('student_game_sessions').select('subject,score,total,points,completed_at').eq('student_id', studentId).order('completed_at', { ascending:false }).limit(100)),
        rows('achievements', client.from('student_achievements').select('*').eq('student_id', studentId).limit(30)),
        rows('activities', activitiesQuery)
      ]);
      Object.assign(state, { grades, attendance, events, announcements, messages, sessions, achievements, activities, loaded:true });
    } catch { state.error = 'Não foi possível atualizar seu espaço agora.'; }
    finally { state.loading = false; render(); }
  }

item91.corpo_render:
function render() {
    const host = root(); if (!host || !isStudent()) return;
    styles();
    identityStyles();
    if (state.loading) { host.innerHTML = loadingMarkup(); return; }
    if (state.error) { host.innerHTML = `<div class="bfr-student-space"><div class="bfr-student-error">${esc(state.error)}</div><button type="button" class="bfr-student-button primary" data-student-refresh>Tentar novamente</button></div>`; return; }
    if (!state.loaded || !state.linked) { host.innerHTML = `<div class="bfr-student-space"><section class="bfr-student-hero"><div><div class="eyebrow">Área do aluno</div><h1>Meu Espaço</h1><p>Seu painel pessoal ficará disponível assim que a escola concluir o vínculo do seu cadastro.</p></div></section>${empty('Ainda não encontramos um aluno vinculado a esta conta. Fale com a secretaria para conferir seu cadastro.')}</div>`; return; }
     host.innerHTML = shellMarkup();
     applyIdentity();
  }
